@Override
public List<Parser> getAllComponentParsers() {
    List<Parser> parsers = super.getAllComponentParsers();
    if (loader != null) {
        parsers = new ArrayList<>(parsers);
        parsers.addAll(loader.loadDynamicServiceProviders(Parser.class));
    }
    return parsers;
}
